        _ = &start_index;
        end_index = (end_index + 1);
        while ((input[@as(usize, @intCast(start_index))] != 47)) {
            if ((start_index == 0)) {
                return input[0..end_index];
            }
            start_index = (start_index - 1);
        }
        return input[(start_index + 1)..end_index];
